using System.Globalization;
using System.Text;
using Dapper;
using Npgsql;
using PlantaoPro.Api.Models;

namespace PlantaoPro.Api;

public enum OperationalReportKind { Cobertura, Execucao, Apuracao }
public sealed record OperationalReportFilter(DateOnly Inicio, DateOnly Fim, Guid? UnidadeId, Guid? EspecialidadeId, Guid? ProfissionalId, string? Situacao, int Page = 1, int PageSize = 25);
public sealed record OperationalReportIndicator(string Code, string Label, decimal Value, string Unit, string? DetailStatus, string Definition);
public sealed record OperationalReportRow(Guid Id, string Reference, string Unit, string Professional, DateTime PeriodDate, string Status, decimal? Value, string ActionUrl);
public sealed record OperationalReportResult(string Code, string Title, string TimeCriterion, DateTime GeneratedAtUtc, IReadOnlyList<OperationalReportIndicator> Indicators, IReadOnlyList<OperationalReportRow> Items, long Total, int Page, int PageSize, bool CurrentState, string? DetailStatus);

public sealed class OperationalReportExportException : Exception
{
    public OperationalReportExportException(string message, int statusCode) : base(message)
    {
        StatusCode = statusCode;
    }

    public int StatusCode { get; }
}

public sealed class OperationalReportService
{
    private readonly IConfiguration configuration; private readonly ICurrentUserService current; private readonly PermissionGuardService permission; private readonly TenantGuardService tenantGuard;
    public OperationalReportService(IConfiguration configuration, ICurrentUserService current, PermissionGuardService permission, TenantGuardService tenantGuard)
    { this.configuration=configuration; this.current=current; this.permission=permission; this.tenantGuard=tenantGuard; }

    public async Task<ApiResponse<OperationalReportResult>> GetAsync(OperationalReportKind kind, OperationalReportFilter filter, CancellationToken ct)
    {
        var required = kind == OperationalReportKind.Apuracao ? PermissionConstants.FinanceiroVer : PermissionConstants.RelatoriosVer;
        var access = await permission.ValidarPermissaoAsync(required); if (!access.Success) return ApiResponse<OperationalReportResult>.Fail(access.Message, access.StatusCode);
        if (filter.Fim < filter.Inicio || filter.Fim.DayNumber-filter.Inicio.DayNumber > 366) return ApiResponse<OperationalReportResult>.Fail("Informe um período válido de até 366 dias.",422);
        if (filter.UnidadeId.HasValue && (!current.UserId.HasValue || !await tenantGuard.PodeAcessarHospitalAsync(current.UserId.Value,filter.UnidadeId.Value))) return ApiResponse<OperationalReportResult>.Fail("Unidade indisponível no contexto atual.",403);
        if (filter.ProfissionalId.HasValue && (!current.UserId.HasValue || !await tenantGuard.PodeAcessarMedicoAsync(current.UserId.Value,filter.ProfissionalId.Value))) return ApiResponse<OperationalReportResult>.Fail("Profissional indisponível no contexto atual.",403);
        if (!current.TenantId.HasValue || !current.ClienteId.HasValue) return ApiResponse<OperationalReportResult>.Fail("Contexto organizacional válido é obrigatório.",403);
        var status=(filter.Situacao??"").Trim().ToUpperInvariant(); var valid=Statuses(kind); if (status.Length>0 && !valid.Contains(status)) return ApiResponse<OperationalReportResult>.Fail("Situação inválida para o relatório.",422);
        var page=Math.Max(1,filter.Page); var size=Math.Clamp(filter.PageSize,1,5000); var args=new { Tenant=current.TenantId.Value, Cliente=current.ClienteId.Value, inicio=filter.Inicio.ToDateTime(TimeOnly.MinValue,DateTimeKind.Utc), fim=filter.Fim.AddDays(1).ToDateTime(TimeOnly.MinValue,DateTimeKind.Utc), filter.UnidadeId, filter.EspecialidadeId, filter.ProfissionalId, status, limit=size, offset=(page-1)*size };
        await using var cn=new NpgsqlConnection(configuration.GetConnectionString("Default"));
        var multi=await cn.QueryMultipleAsync(new CommandDefinition(Sql(kind),args,cancellationToken:ct));
        var metrics=(await multi.ReadAsync<Metric>()).ToDictionary(x=>x.Code,x=>x.Value,StringComparer.OrdinalIgnoreCase); var total=await multi.ReadSingleAsync<long>(); var rows=(await multi.ReadAsync<OperationalReportRow>()).AsList();
        var result=new OperationalReportResult(kind.ToString().ToUpperInvariant(),Title(kind),Criterion(kind),DateTime.UtcNow,Indicators(kind,metrics),rows,total,page,size,true,status.Length==0?null:status);
        return ApiResponse<OperationalReportResult>.Ok(result,"Relatório atualizado com a situação atual dos registros do período.");
    }
    public async Task<(byte[] Content,string Name)> CsvAsync(OperationalReportKind kind, OperationalReportFilter filter,CancellationToken ct)
    {
        var all = filter with { Page = 1, PageSize = 5000 };
        var response = await GetAsync(kind, all, ct);
        if (!response.Success || response.Data is null)
            throw new OperationalReportExportException(response.Message, response.StatusCode);

        var sb = new StringBuilder("\uFEFFReferência;Unidade;Profissional;Data;Situação;Valor\r\n");
        foreach (var row in response.Data.Items)
        {
            sb.AppendLine(string.Join(';', new[]
            {
                EscapeCsvField(row.Reference),
                EscapeCsvField(row.Unit),
                EscapeCsvField(row.Professional),
                row.PeriodDate.ToString("yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture),
                EscapeCsvField(row.Status),
                row.Value?.ToString("0.00", CultureInfo.InvariantCulture) ?? ""
            }));
        }

        return (Encoding.UTF8.GetBytes(sb.ToString()), $"{response.Data.Code.ToLowerInvariant()}-{DateTime.UtcNow:yyyyMMddHHmmss}.csv");
    }

    internal static string EscapeCsvField(string value)
    {
        var escaped = value.Replace("\"", "\"\"").Replace("\r", " ").Replace("\n", " ");
        if (escaped.Length > 0 && "=+-@".Contains(escaped[0])) escaped = "'" + escaped;
        return escaped.Contains(';') || escaped.Contains('"') ? $"\"{escaped}\"" : escaped;
    }
    private static HashSet<string> Statuses(OperationalReportKind k)=>new((k switch { OperationalReportKind.Cobertura=>new[]{"ATRIBUIDA","CONFIRMADA","DESCOBERTA","SUBSTITUIDA"},OperationalReportKind.Execucao=>new[]{"REGISTRO_INCOMPLETO","PENDENTE","CORRECAO_PENDENTE","APROVADA","AJUSTE_POS_APURACAO"},_=>new[]{"APURADO","FECHADO","PAGO","PENDENTE"}}),StringComparer.OrdinalIgnoreCase);
    private static string Title(OperationalReportKind k)=>k switch{OperationalReportKind.Cobertura=>"Cobertura de escalas",OperationalReportKind.Execucao=>"Execução e conferência",_=>"Apuração por período"};
    private static string Criterion(OperationalReportKind k)=>k switch{OperationalReportKind.Cobertura=>"início do plantão (intervalo semiaberto no fuso persistido)",OperationalReportKind.Execucao=>"início do plantão associado à execução",_=>"competência pelo início do plantão; pago pela data de pagamento"};
    private static IReadOnlyList<OperationalReportIndicator> Indicators(OperationalReportKind k,Dictionary<string,decimal> m)=>Definitions(k).Select(x=>new OperationalReportIndicator(x.Code,x.Label,m.GetValueOrDefault(x.Code),x.Unit,x.Status,x.Definition)).ToArray();
    private static (string Code,string Label,string Unit,string? Status,string Definition)[] Definitions(OperationalReportKind k)=>k switch{
      OperationalReportKind.Cobertura=>new[]{("planned","Vagas planejadas","vagas",(string?)null,"Soma de vagas dos plantões iniciados no período."),("assigned","Vagas atribuídas","vagas","ATRIBUIDA","Atribuições ativas; não implica confirmação."),("confirmed","Vagas confirmadas","vagas","CONFIRMADA","Atribuições ativas em situação confirmada/realizada."),("uncovered","Vagas descobertas","vagas","DESCOBERTA","Máximo entre vagas planejadas menos atribuições ativas e zero."),("substituted","Substituições efetivadas","substituições","SUBSTITUIDA","Pedidos confirmados com nova atribuição vinculada.")},
      OperationalReportKind.Execucao=>new[]{("registered","Execuções registradas","execuções",(string?)null,"Presenças com check-in registradas."),("incomplete","Execuções incompletas","execuções","REGISTRO_INCOMPLETO","Presenças sem saída ou marcadas como incompletas."),("waiting","Aguardando conferência","execuções","PENDENTE","Presenças no estado atual PENDENTE."),("corrections","Correções pendentes","correções","CORRECAO_PENDENTE","Presenças com correção pendente, contadas uma vez."),("approved","Execuções aprovadas","execuções","APROVADA","Presenças no estado atual APROVADA.")},
      _=>new[]{("assessed","Valores apurados","R$",(string?)null,"Soma de valor_apurado dos fechamentos do período."),("closed","Valores fechados","R$","FECHADO","Valor apurado de fechamentos FECHADO ou CONCLUIDO."),("paid","Valores pagos","R$","PAGO","Soma de pagamentos pagos, pela data de pagamento dentro do período."),("adjustments","Ajustes","R$",(string?)null,"Diferença entre valor resolvido e original de contestações resolvidas."),("blocking","Pendências impeditivas","pendências","PENDENTE","Divergências abertas dos fechamentos, sem multiplicar valores.")}};
    private static string Sql(OperationalReportKind k)=>k switch {
OperationalReportKind.Cobertura=>@"with base as (select p.id,p.data_inicio,p.hospital_id,p.especialidade_id,p.vagas,coalesce(h.nome_fantasia,h.razao_social,'') unidade from plantaopro.plantoes p join plantaopro.hospitais h on h.id=p.hospital_id where p.reg_status='A' and p.cliente_id=@Cliente and p.data_inicio>=@inicio and p.data_inicio<@fim and (@UnidadeId is null or p.hospital_id=@UnidadeId) and (@EspecialidadeId is null or p.especialidade_id=@EspecialidadeId)), a as (select e.plantao_id,count(*) n,count(*) filter(where lower(e.status) in ('confirmado','confirmada','realizado','realizada')) confirmed from plantaopro.escalas e join base b on b.id=e.plantao_id where e.reg_status='A' and (@ProfissionalId is null or e.medico_id=@ProfissionalId) group by e.plantao_id), s as(select count(*) n from plantaopro.substituicoes_plantao s join base b on b.id=s.plantao_id where s.reg_status='A' and s.status='CONFIRMADA' and s.nova_escala_id is not null) select * from (values('planned',(select coalesce(sum(vagas),0) from base)),('assigned',(select coalesce(sum(n),0) from a)),('confirmed',(select coalesce(sum(confirmed),0) from a)),('uncovered',(select coalesce(sum(greatest(b.vagas-coalesce(a.n,0),0)),0) from base b left join a on a.plantao_id=b.id)),('substituted',(select n from s)))m(""Code"",""Value""); with base as (select p.id,p.data_inicio,p.hospital_id,p.especialidade_id,p.vagas,coalesce(h.nome_fantasia,h.razao_social,'') unidade from plantaopro.plantoes p join plantaopro.hospitais h on h.id=p.hospital_id where p.reg_status='A' and p.cliente_id=@Cliente and p.data_inicio>=@inicio and p.data_inicio<@fim and (@UnidadeId is null or p.hospital_id=@UnidadeId) and (@EspecialidadeId is null or p.especialidade_id=@EspecialidadeId)), a as (select e.plantao_id,count(*) n,count(*) filter(where lower(e.status) in ('confirmado','confirmada','realizado','realizada')) confirmed from plantaopro.escalas e join base b on b.id=e.plantao_id where e.reg_status='A' and (@ProfissionalId is null or e.medico_id=@ProfissionalId) group by e.plantao_id) select count(*) from base b left join a on a.plantao_id=b.id where @status='' or (@status='DESCOBERTA' and b.vagas>coalesce(a.n,0)) or (@status='ATRIBUIDA' and coalesce(a.n,0)>0) or (@status='CONFIRMADA' and coalesce(a.confirmed,0)>0) or (@status='SUBSTITUIDA' and exists(select 1 from plantaopro.substituicoes_plantao s where s.plantao_id=b.id and s.status='CONFIRMADA' and s.nova_escala_id is not null)); with base as (select p.id,p.data_inicio,p.hospital_id,p.especialidade_id,p.vagas,coalesce(h.nome_fantasia,h.razao_social,'') unidade from plantaopro.plantoes p join plantaopro.hospitais h on h.id=p.hospital_id where p.reg_status='A' and p.cliente_id=@Cliente and p.data_inicio>=@inicio and p.data_inicio<@fim and (@UnidadeId is null or p.hospital_id=@UnidadeId) and (@EspecialidadeId is null or p.especialidade_id=@EspecialidadeId)), a as (select e.plantao_id,count(*) n,count(*) filter(where lower(e.status) in ('confirmado','confirmada','realizado','realizada')) confirmed from plantaopro.escalas e join base b on b.id=e.plantao_id where e.reg_status='A' and (@ProfissionalId is null or e.medico_id=@ProfissionalId) group by e.plantao_id) select b.id as ""Id"",coalesce(b.id::text,'') as ""Reference"",b.unidade as ""Unit"",'' as ""Professional"",b.data_inicio as ""PeriodDate"",case when b.vagas>coalesce(a.n,0) then 'DESCOBERTA' when coalesce(a.confirmed,0)>0 then 'CONFIRMADA' else 'ATRIBUIDA' end as ""Status"",null::numeric as ""Value"",('/Plantoes/Details/'||b.id::text) as ""ActionUrl"" from base b left join a on a.plantao_id=b.id where @status='' or (@status='DESCOBERTA' and b.vagas>coalesce(a.n,0)) or (@status='ATRIBUIDA' and coalesce(a.n,0)>0) or (@status='CONFIRMADA' and coalesce(a.confirmed,0)>0) or (@status='SUBSTITUIDA' and exists(select 1 from plantaopro.substituicoes_plantao s where s.plantao_id=b.id and s.status='CONFIRMADA' and s.nova_escala_id is not null)) order by b.data_inicio,b.id limit @limit offset @offset;",
OperationalReportKind.Execucao=>@"with base as(select c.id,c.checkin_em,c.checkout_em,c.status_conferencia,p.data_inicio,coalesce(h.nome_fantasia,h.razao_social,'') unidade,m.nome profissional from medico_checkins c join plantaopro.escalas e on e.id=c.escala_id and e.reg_status='A' join plantaopro.plantoes p on p.id=e.plantao_id and p.cliente_id=@Cliente and p.reg_status='A' join plantaopro.hospitais h on h.id=p.hospital_id join plantaopro.medicos m on m.id=c.medico_id where c.tenant_id=@Tenant and p.data_inicio>=@inicio and p.data_inicio<@fim and (@UnidadeId is null or p.hospital_id=@UnidadeId) and (@EspecialidadeId is null or p.especialidade_id=@EspecialidadeId) and (@ProfissionalId is null or c.medico_id=@ProfissionalId)), metrics as(select count(*) registered,count(*) filter(where checkout_em is null or status_conferencia='REGISTRO_INCOMPLETO') incomplete,count(*) filter(where status_conferencia='PENDENTE') waiting,count(*) filter(where status_conferencia='CORRECAO_PENDENTE') corrections,count(*) filter(where status_conferencia='APROVADA') approved from base) select * from (select 'registered' ""Code"",registered ""Value"" from metrics union all select 'incomplete',incomplete from metrics union all select 'waiting',waiting from metrics union all select 'corrections',corrections from metrics union all select 'approved',approved from metrics)x; with base as(select c.id,c.checkin_em,c.checkout_em,c.status_conferencia,p.data_inicio,coalesce(h.nome_fantasia,h.razao_social,'') unidade,m.nome profissional from medico_checkins c join plantaopro.escalas e on e.id=c.escala_id and e.reg_status='A' join plantaopro.plantoes p on p.id=e.plantao_id and p.cliente_id=@Cliente and p.reg_status='A' join plantaopro.hospitais h on h.id=p.hospital_id join plantaopro.medicos m on m.id=c.medico_id where c.tenant_id=@Tenant and p.data_inicio>=@inicio and p.data_inicio<@fim and (@UnidadeId is null or p.hospital_id=@UnidadeId) and (@EspecialidadeId is null or p.especialidade_id=@EspecialidadeId) and (@ProfissionalId is null or c.medico_id=@ProfissionalId)) select count(*) from base where @status='' or status_conferencia=@status; with base as(select c.id,c.checkin_em,c.checkout_em,c.status_conferencia,p.data_inicio,coalesce(h.nome_fantasia,h.razao_social,'') unidade,m.nome profissional from medico_checkins c join plantaopro.escalas e on e.id=c.escala_id and e.reg_status='A' join plantaopro.plantoes p on p.id=e.plantao_id and p.cliente_id=@Cliente and p.reg_status='A' join plantaopro.hospitais h on h.id=p.hospital_id join plantaopro.medicos m on m.id=c.medico_id where c.tenant_id=@Tenant and p.data_inicio>=@inicio and p.data_inicio<@fim and (@UnidadeId is null or p.hospital_id=@UnidadeId) and (@EspecialidadeId is null or p.especialidade_id=@EspecialidadeId) and (@ProfissionalId is null or c.medico_id=@ProfissionalId)) select id as ""Id"",id::text as ""Reference"",unidade as ""Unit"",profissional as ""Professional"",data_inicio as ""PeriodDate"",status_conferencia as ""Status"",null::numeric as ""Value"",('/ConferenciaExecucao?presencaId='||id::text) as ""ActionUrl"" from base where @status='' or status_conferencia=@status order by data_inicio,id limit @limit offset @offset;",
_=>@"with base as(select f.id,f.plantao_id,f.valor_apurado,f.status,p.data_inicio,coalesce(h.nome_fantasia,h.razao_social,'') unidade from plantaopro.fechamento_plantao f join plantaopro.plantoes p on p.id=f.plantao_id and p.cliente_id=@Cliente join plantaopro.hospitais h on h.id=p.hospital_id where f.tenant_id=@Tenant and p.data_inicio>=@inicio and p.data_inicio<@fim and (@UnidadeId is null or p.hospital_id=@UnidadeId) and (@EspecialidadeId is null or p.especialidade_id=@EspecialidadeId)), paid as(select coalesce(sum(pg.valor_pago),0) value from plantaopro.pagamentos pg where pg.tenant_id=@Tenant and pg.reg_status='A' and lower(pg.status)='pago' and pg.data_pagamento>=@inicio::date and pg.data_pagamento<@fim::date and (@ProfissionalId is null or pg.medico_id=@ProfissionalId)), adj as(select coalesce(sum(coalesce(valor_resolvido,valor_original)-valor_original),0) value from plantaopro.pagamento_contestacoes where tenant_id=@Tenant and status='RESOLVIDA' and resolvido_em>=@inicio and resolvido_em<@fim), blockers as(select count(*) n from plantaopro.fechamento_divergencias d join base b on b.id=d.fechamento_id where d.status='ABERTA') select * from(values('assessed',(select coalesce(sum(valor_apurado),0) from base)),('closed',(select coalesce(sum(valor_apurado),0) from base where status in('FECHADO','CONCLUIDO'))),('paid',(select value from paid)),('adjustments',(select value from adj)),('blocking',(select n from blockers)))m(""Code"",""Value""); with base as(select f.id,f.plantao_id,f.valor_apurado,f.status,p.data_inicio,coalesce(h.nome_fantasia,h.razao_social,'') unidade from plantaopro.fechamento_plantao f join plantaopro.plantoes p on p.id=f.plantao_id and p.cliente_id=@Cliente join plantaopro.hospitais h on h.id=p.hospital_id where f.tenant_id=@Tenant and p.data_inicio>=@inicio and p.data_inicio<@fim and (@UnidadeId is null or p.hospital_id=@UnidadeId) and (@EspecialidadeId is null or p.especialidade_id=@EspecialidadeId)) select count(*) from base where @status='' or (@status='FECHADO' and status in('FECHADO','CONCLUIDO')) or (@status='APURADO') or (@status='PENDENTE' and status in('EM_CONFERENCIA','COM_DIVERGENCIA','DEVOLVIDO')); with base as(select f.id,f.plantao_id,f.valor_apurado,f.status,p.data_inicio,coalesce(h.nome_fantasia,h.razao_social,'') unidade from plantaopro.fechamento_plantao f join plantaopro.plantoes p on p.id=f.plantao_id and p.cliente_id=@Cliente join plantaopro.hospitais h on h.id=p.hospital_id where f.tenant_id=@Tenant and p.data_inicio>=@inicio and p.data_inicio<@fim and (@UnidadeId is null or p.hospital_id=@UnidadeId) and (@EspecialidadeId is null or p.especialidade_id=@EspecialidadeId)) select id as ""Id"",id::text as ""Reference"",unidade as ""Unit"",'' as ""Professional"",data_inicio as ""PeriodDate"",status as ""Status"",valor_apurado as ""Value"",('/fechamentos/'||id::text) as ""ActionUrl"" from base where @status='' or (@status='FECHADO' and status in('FECHADO','CONCLUIDO')) or (@status='APURADO') or (@status='PENDENTE' and status in('EM_CONFERENCIA','COM_DIVERGENCIA','DEVOLVIDO')) order by data_inicio,id limit @limit offset @offset;"};
    private sealed record Metric(string Code,decimal Value);
}
